What does this print? Write the two numbers separated by a space.

```rust
use std::rc::Rc;

fn main() {
    let a = Rc::new(String::from("x"));
    let b = Rc::clone(&a);
    {
        let c = Rc::clone(&b);
        println!("{}", Rc::strong_count(&c));
    }
    println!("{}", Rc::strong_count(&a));
}
```

